import{_ as e,c as a,o,ae as s}from"./chunks/framework.CliRSA9F.js";const u=JSON.parse('{"title":"AI Connections","description":"Connect Claude, ChatGPT or Cursor to your PodSEO account and ask questions about your podcasts, keywords, rankings, competitors and connected analytics. Read-only, on paid plans.","frontmatter":{"description":"Connect Claude, ChatGPT or Cursor to your PodSEO account and ask questions about your podcasts, keywords, rankings, competitors and connected analytics. Read-only, on paid plans."},"headers":[],"relativePath":"features/ai-connections.md","filePath":"features/ai-connections.md"}'),n={name:"features/ai-connections.md"};function i(r,t,c,d,h,l){return o(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="ai-connections" tabindex="-1">AI Connections <a class="header-anchor" href="#ai-connections" aria-label="Permalink to &quot;AI Connections&quot;">​</a></h1><h2 id="ask-claude-chatgpt-or-cursor-about-your-podseo-data" tabindex="-1">Ask Claude, ChatGPT or Cursor About Your PodSEO Data <a class="header-anchor" href="#ask-claude-chatgpt-or-cursor-about-your-podseo-data" aria-label="Permalink to &quot;Ask Claude, ChatGPT or Cursor About Your PodSEO Data&quot;">​</a></h2><p>AI connections let you connect an AI assistant you already use, such as <strong>Claude</strong>, <strong>ChatGPT</strong> or <strong>Cursor</strong>, to your PodSEO account. Once connected, you can ask the assistant questions in your own words (&quot;Which of my tracked keywords dropped on Spotify this month?&quot;, &quot;Compare my last five episodes&#39; downloads&quot;, &quot;How does my Apple ranking compare with my main competitor&#39;s?&quot;) and it answers with your real PodSEO data: your podcasts, tracked keywords and rankings, competitors, ratings, AI visibility and the analytics you&#39;ve connected.</p><p>It&#39;s useful when you want to combine numbers that live on different PodSEO pages, write a report in your own format, or think through a strategy with an assistant that can look up the facts as you talk.</p><p><strong>Who can use it</strong>: AI connections are included in every <strong>paid plan</strong> (Podcaster, Producer, Agency, Enterprise). On the Free plan, PodSEO shows an upgrade page when you try to connect.</p><p><strong>Read-only</strong>: the assistant can <strong>read</strong> your PodSEO data. It can&#39;t change anything: it can&#39;t add or remove keywords, edit competitors, change your Planner or settings, or publish anything.</p><hr><h2 id="what-you-need" tabindex="-1"><strong>What You Need</strong> <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;**What You Need**&quot;">​</a></h2><ul><li>A PodSEO account on a paid plan (or membership in an organization on a paid plan).</li><li>An AI assistant that supports custom connectors (also called MCP servers or custom apps). Claude, ChatGPT and Cursor all do, though availability can depend on your plan with that assistant.</li><li>The PodSEO server URL:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://mcp.podseo.com/mcp</span></span></code></pre></div><p>You can also copy the URL from <strong>Settings → AI connections</strong> in PodSEO.</p><hr><h2 id="how-to-connect" tabindex="-1"><strong>How to Connect</strong> <a class="header-anchor" href="#how-to-connect" aria-label="Permalink to &quot;**How to Connect**&quot;">​</a></h2><p>Every assistant follows the same pattern: you add PodSEO using the server URL, sign in to PodSEO, and approve the connection. The menus differ between assistants and can change. The steps below were checked against their official setup guides on October 22, 2026.</p><h3 id="claude-claude-ai-and-the-claude-desktop-app" tabindex="-1"><strong>Claude (claude.ai and the Claude Desktop app)</strong> <a class="header-anchor" href="#claude-claude-ai-and-the-claude-desktop-app" aria-label="Permalink to &quot;**Claude (claude.ai and the Claude Desktop app)**&quot;">​</a></h3><ol><li>Open <strong>Customize → Connectors</strong>, then <strong>+ Add → Add custom connector</strong>.</li><li>Name it &quot;PodSEO&quot;, paste <code>https://mcp.podseo.com/mcp</code> as the server URL, and continue.</li><li>Choose <strong>Sign in now</strong> and <strong>Use Claude’s published identity</strong> when asked about authentication, then finish adding the connector.</li><li>Sign in to PodSEO and approve the connection when prompted. If the connector is listed but not connected, click <strong>Connect</strong>.</li><li>Enable PodSEO for your conversation from the <strong>+ → Connectors</strong> menu, then ask your question.</li></ol><p>On Team and Enterprise, an owner or another permitted administrator must first add it through <strong>Organization settings → Connectors → Add → Custom → Web</strong>. Members then connect individually. Remote connectors are available across Claude web, Desktop and mobile on the same account.</p><p>See <a href="https://support.claude.com/en/articles/11175166-get-started-with-custom-connectors-using-remote-mcp" target="_blank" rel="noreferrer">Claude’s official connector guide</a> for current menus and workspace permissions.</p><h3 id="claude-code" tabindex="-1"><strong>Claude Code</strong> <a class="header-anchor" href="#claude-code" aria-label="Permalink to &quot;**Claude Code**&quot;">​</a></h3><ol><li>In your terminal, add PodSEO as a remote server:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude mcp add --transport http podseo https://mcp.podseo.com/mcp</span></span></code></pre></div></li><li>Start Claude Code and run <code>/mcp</code>, select <strong>podseo</strong> and choose to authenticate. Your browser opens PodSEO: sign in and approve the connection.</li></ol><p>See <a href="https://code.claude.com/docs/en/mcp" target="_blank" rel="noreferrer">Claude Code’s MCP guide</a> for configuration options.</p><h3 id="chatgpt" tabindex="-1"><strong>ChatGPT</strong> <a class="header-anchor" href="#chatgpt" aria-label="Permalink to &quot;**ChatGPT**&quot;">​</a></h3><ol><li>On ChatGPT’s website, open <strong>Plugins</strong>, select <strong>+</strong>, then <strong>Add custom MCP server</strong>.</li><li>Name it &quot;PodSEO&quot; and enter <code>https://mcp.podseo.com/mcp</code> under <strong>Connection → Server URL</strong>.</li><li>Choose <strong>OAuth</strong> authentication. Leave the client ID and client secret blank; select <strong>CIMD</strong> if asked how to identify the client.</li><li>Review the connection notice and select <strong>Create as a plugin</strong>. Find PodSEO in your plugins and install it.</li><li>In a chat, type <strong>@</strong> and select PodSEO. When prompted, sign in to PodSEO and approve the connection.</li></ol><p>Workspace permissions and security settings can restrict custom plugins. If the option is unavailable, check with your workspace administrator. See <a href="https://developers.openai.com/api/docs/guides/custom-mcp-server" target="_blank" rel="noreferrer">OpenAI’s custom MCP setup guide</a> for the current process.</p><h3 id="cursor" tabindex="-1"><strong>Cursor</strong> <a class="header-anchor" href="#cursor" aria-label="Permalink to &quot;**Cursor**&quot;">​</a></h3><p>Manage MCP servers from <strong>Customize</strong>, or configure PodSEO in <code>mcp.json</code>:</p><ol><li>Open <code>~/.cursor/mcp.json</code> for access across projects, or <code>.cursor/mcp.json</code> within one project.</li><li>Add the <code>podseo</code> entry below. If the file already lists servers, keep them and add <code>podseo</code> inside the existing <code>mcpServers</code> object.<div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;podseo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://mcp.podseo.com/mcp&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li>Save the file and follow Cursor’s sign-in prompt. In your browser, sign in to PodSEO and approve the connection.</li></ol><p>No API key or manually created client credentials are needed. See <a href="https://cursor.com/docs/mcp" target="_blank" rel="noreferrer">Cursor’s MCP guide</a> for current setup options.</p><h3 id="other-assistants" tabindex="-1"><strong>Other assistants</strong> <a class="header-anchor" href="#other-assistants" aria-label="Permalink to &quot;**Other assistants**&quot;">​</a></h3><p>For another assistant, check that it supports <strong>Streamable HTTP</strong> and <strong>OAuth sign-in</strong> for remote MCP servers. Add <code>https://mcp.podseo.com/mcp</code> as the server URL, then sign in to PodSEO and approve. Setup varies by client; the instructions above cover Claude, Claude Code, ChatGPT and Cursor.</p><hr><h2 id="approving-the-connection" tabindex="-1"><strong>Approving the Connection</strong> <a class="header-anchor" href="#approving-the-connection" aria-label="Permalink to &quot;**Approving the Connection**&quot;">​</a></h2><p>When the assistant sends you to PodSEO, sign in with your usual PodSEO login. PodSEO then shows a consent page that:</p><ul><li>Names the assistant that is asking to connect. When PodSEO can verify where the request comes from (for example, Claude or ChatGPT), it says so. If you see a warning that PodSEO hasn&#39;t verified the app, only continue if you started the connection yourself and expect to be sent back to the site shown.</li><li>Lets you <strong>choose the account the assistant can read</strong>: your personal account or an organization you belong to. Accounts that aren&#39;t on a paid plan are shown but can&#39;t be selected.</li><li>Confirms that the assistant can only read, and that the analytics connected to that account are included (YouTube data is not).</li></ul><p>Click <strong>Allow</strong> to finish. You&#39;re sent back to the assistant and can start asking questions.</p><p><strong>One account per assistant.</strong> Each assistant reads one PodSEO account at a time. To have it read a different account (for example, your organization instead of your personal account), connect it again and pick the other account: the earlier connection is replaced.</p><p><strong>In an organization</strong>, the assistant sees what you can see in PodSEO for that account. If you&#39;ve been given access to only some of the organization&#39;s podcasts, the assistant sees only those.</p><hr><h2 id="what-the-assistant-can-read" tabindex="-1"><strong>What the Assistant Can Read</strong> <a class="header-anchor" href="#what-the-assistant-can-read" aria-label="Permalink to &quot;**What the Assistant Can Read**&quot;">​</a></h2><p>The assistant can read the same information PodSEO shows you in the app, for the account you approved:</p><ul><li><strong>Your podcasts</strong>: details, metadata and episodes, and the history of changes to your episode titles and descriptions.</li><li><strong>Keywords and rankings</strong>: your tracked keywords and how your show ranks for them on Apple Podcasts, Spotify, Amazon Music, YouTube Music and YouTube, the search results for your tracked keywords, your episodes&#39; keyword rankings and episode SEO scores.</li><li><strong>Competitors</strong>: your tracked competitors and how they rank for your tracked keywords.</li><li><strong>Ratings and reviews</strong>: ratings across platforms and Apple Podcasts reviews.</li><li><strong>Charts and editorial</strong>: your chart positions and editorial features.</li><li><strong>Visibility</strong>: your <a href="/getting-started/visibility-score-explained.html">Visibility Score</a> and rank, and their history.</li><li><strong>AI visibility</strong>: whether ChatGPT, Claude, Perplexity and Gemini mention your podcast, and the weekly trend (see <a href="/features/ai-mentions.html">AI Mentions</a>).</li><li><strong>Related podcasts</strong>, your <strong>Planner</strong>, your <strong>positioning</strong>, keyword groups, recommendations and <strong>distribution health</strong>.</li><li><strong>Your plan</strong>: plan limits and credits.</li><li><strong>Connected analytics</strong> (see <a href="/features/analytics-connections.html">Analytics Connections</a>): <ul><li>Downloads and audience from your <strong>podcast host</strong> (Spreaker, Buzzsprout), <strong>OP3</strong> and <strong>hopr.fm</strong></li><li><strong>Spotify for Creators</strong>: plays, listeners, impressions and discovery, retention, benchmarks and episode details</li><li><strong>Apple Podcasts Connect</strong>: plays, listeners, followers, episodes and reports</li></ul></li></ul><h3 id="what-it-can-t-read" tabindex="-1"><strong>What it can&#39;t read</strong> <a class="header-anchor" href="#what-it-can-t-read" aria-label="Permalink to &quot;**What it can&#39;t read**&quot;">​</a></h3><ul><li><strong>YouTube analytics</strong>: your YouTube channel&#39;s data from <a href="/features/youtube-insights.html">YouTube Insights</a> is not shared with AI assistants. The assistant can only tell whether YouTube is connected.</li><li><strong>Keywords and competitors you don&#39;t track</strong>: the assistant works with your tracked keywords and competitors, within your plan&#39;s limits. It can&#39;t look up new keywords or research shows you haven&#39;t added.</li><li><strong>Anything beyond your plan</strong>: if your account is over a plan limit (for example after moving to a smaller plan), the podcasts, keywords and competitors above the limit aren&#39;t readable, just as in the app.</li><li><strong>Analytics you haven&#39;t connected or have disconnected</strong>: a disconnected source shows no numbers.</li><li><strong>Other people&#39;s accounts</strong>: only the account you approved.</li></ul><h3 id="your-data-the-assistant-s-analysis" tabindex="-1"><strong>Your data, the assistant&#39;s analysis</strong> <a class="header-anchor" href="#your-data-the-assistant-s-analysis" aria-label="Permalink to &quot;**Your data, the assistant&#39;s analysis**&quot;">​</a></h3><p>PodSEO gives the assistant your data and PodSEO&#39;s own scores (such as the Visibility Score and episode SEO scores). The analysis, summaries and advice you get in the conversation are written by the assistant itself, not by PodSEO. If you want PodSEO&#39;s own guidance, use <a href="/features/lucia-ai-assistant.html">LUCIA</a> inside the app.</p><hr><h2 id="privacy" tabindex="-1"><strong>Privacy</strong> <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;**Privacy**&quot;">​</a></h2><ul><li>PodSEO sends data to the assistant <strong>only when the assistant asks for it on your behalf</strong>, while you&#39;re using it.</li><li>Once the assistant receives your data, the assistant&#39;s provider (for example Anthropic for Claude or OpenAI for ChatGPT) handles it under its own terms and privacy policy, including any copies kept in your conversations.</li><li>YouTube data is never shared with AI assistants.</li></ul><p>Read the full details in the <strong>AI Assistant Connections</strong> section of the <a href="https://podseo.com/privacy-policy/#ai-assistant-connections" target="_blank" rel="noreferrer">PodSEO Privacy Policy</a>.</p><hr><h2 id="disconnecting" tabindex="-1"><strong>Disconnecting</strong> <a class="header-anchor" href="#disconnecting" aria-label="Permalink to &quot;**Disconnecting**&quot;">​</a></h2><p>You can disconnect an assistant at any time, in any of these ways:</p><ul><li><strong>In PodSEO</strong>: open <strong>Settings → AI connections</strong>, find the assistant and click <strong>Disconnect</strong>. The assistant loses access within a minute.</li><li><strong>In the assistant</strong>: remove the PodSEO connector from the assistant&#39;s connector or integration settings.</li><li><strong>By email</strong>: write to <a href="mailto:info@podseo.com" target="_blank" rel="noreferrer">info@podseo.com</a> and we&#39;ll disconnect it for you.</li></ul><p>After you disconnect, PodSEO sends the assistant no further data. Deleting your PodSEO account also removes all AI connections.</p><hr><h2 id="troubleshooting" tabindex="-1"><strong>Troubleshooting</strong> <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;**Troubleshooting**&quot;">​</a></h2><h3 id="the-assistant-says-ai-connections-need-a-paid-plan" tabindex="-1"><strong>The assistant says AI connections need a paid plan</strong> <a class="header-anchor" href="#the-assistant-says-ai-connections-need-a-paid-plan" aria-label="Permalink to &quot;**The assistant says AI connections need a paid plan**&quot;">​</a></h3><p>The account you approved isn&#39;t on a paid plan, for example because the subscription ended or was moved to the Free plan. <a href="https://podseo.com/pricing/" target="_blank" rel="noreferrer">Upgrade</a> and the connection works again; you don&#39;t need to reconnect.</p><h3 id="the-consent-page-says-ai-assistant-connections-need-a-paid-plan" tabindex="-1"><strong>The consent page says AI assistant connections need a paid plan</strong> <a class="header-anchor" href="#the-consent-page-says-ai-assistant-connections-need-a-paid-plan" aria-label="Permalink to &quot;**The consent page says AI assistant connections need a paid plan**&quot;">​</a></h3><p>The PodSEO account you signed in with isn&#39;t on a paid plan. Upgrade, or, if you belong to an organization on a paid plan, make sure you&#39;re signing in with the login that belongs to it and pick the organization on the consent page.</p><h3 id="the-assistant-can-t-find-a-podcast-keyword-or-competitor" tabindex="-1"><strong>The assistant can&#39;t find a podcast, keyword or competitor</strong> <a class="header-anchor" href="#the-assistant-can-t-find-a-podcast-keyword-or-competitor" aria-label="Permalink to &quot;**The assistant can&#39;t find a podcast, keyword or competitor**&quot;">​</a></h3><p>It only reads what&#39;s tracked in the account you approved and within your plan&#39;s limits. Check that the podcast, keyword or competitor is tracked in PodSEO. If your account is over a plan limit, the items above the limit aren&#39;t readable until you upgrade or reduce what you track. In an organization, check that you have access to that podcast.</p><h3 id="the-assistant-says-my-spotify-apple-or-host-numbers-aren-t-available" tabindex="-1"><strong>The assistant says my Spotify, Apple or host numbers aren&#39;t available</strong> <a class="header-anchor" href="#the-assistant-says-my-spotify-apple-or-host-numbers-aren-t-available" aria-label="Permalink to &quot;**The assistant says my Spotify, Apple or host numbers aren&#39;t available**&quot;">​</a></h3><p>Connect that source in PodSEO first, on the <a href="/features/analytics-connections.html">Analytics</a> page. If you disconnected it, its numbers aren&#39;t shared. YouTube analytics are never shared.</p><h3 id="the-numbers-look-out-of-date" tabindex="-1"><strong>The numbers look out of date</strong> <a class="header-anchor" href="#the-numbers-look-out-of-date" aria-label="Permalink to &quot;**The numbers look out of date**&quot;">​</a></h3><p>The assistant sees the same numbers PodSEO has, as of PodSEO&#39;s latest update for each source, and it receives the date of that data. Ask the assistant which date the numbers refer to. Each source updates on its own schedule (see <a href="/features/analytics-connections.html">Analytics Connections</a> for how fresh each one is).</p><h3 id="the-assistant-reads-the-wrong-account" tabindex="-1"><strong>The assistant reads the wrong account</strong> <a class="header-anchor" href="#the-assistant-reads-the-wrong-account" aria-label="Permalink to &quot;**The assistant reads the wrong account**&quot;">​</a></h3><p>Each assistant reads the account you picked when you approved it. Connect the assistant again and choose the other account on the consent page.</p><h3 id="the-connection-stopped-working" tabindex="-1"><strong>The connection stopped working</strong> <a class="header-anchor" href="#the-connection-stopped-working" aria-label="Permalink to &quot;**The connection stopped working**&quot;">​</a></h3><p>If you disconnected the assistant in PodSEO, or removed and re-added the connector, reconnect it from the assistant&#39;s connector settings and approve again. If it keeps failing, contact us from <strong>Settings → Contact Us</strong>.</p><hr><h2 id="faq" tabindex="-1"><strong>FAQ</strong> <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;**FAQ**&quot;">​</a></h2><h3 id="can-the-assistant-change-my-keywords-competitors-or-episodes" tabindex="-1"><strong>Can the assistant change my keywords, competitors or episodes?</strong> <a class="header-anchor" href="#can-the-assistant-change-my-keywords-competitors-or-episodes" aria-label="Permalink to &quot;**Can the assistant change my keywords, competitors or episodes?**&quot;">​</a></h3><p>No. The connection is read-only. The assistant can read your data but can&#39;t add, remove or edit anything in PodSEO, and it can&#39;t publish anything.</p><h3 id="can-chatgpt-or-claude-see-my-spotify-and-apple-stats" tabindex="-1"><strong>Can ChatGPT or Claude see my Spotify and Apple stats?</strong> <a class="header-anchor" href="#can-chatgpt-or-claude-see-my-spotify-and-apple-stats" aria-label="Permalink to &quot;**Can ChatGPT or Claude see my Spotify and Apple stats?**&quot;">​</a></h3><p>Yes, if you&#39;ve connected Spotify for Creators or Apple Podcasts Connect in PodSEO&#39;s Analytics page. The same goes for your host (Spreaker, Buzzsprout), OP3 and hopr.fm. YouTube analytics aren&#39;t shared.</p><h3 id="is-it-included-in-my-plan" tabindex="-1"><strong>Is it included in my plan?</strong> <a class="header-anchor" href="#is-it-included-in-my-plan" aria-label="Permalink to &quot;**Is it included in my plan?**&quot;">​</a></h3><p>AI connections are included in every paid plan, with no extra charge. They aren&#39;t available on the Free plan.</p><h3 id="does-using-the-assistant-cost-podseo-credits" tabindex="-1"><strong>Does using the assistant cost PodSEO credits?</strong> <a class="header-anchor" href="#does-using-the-assistant-cost-podseo-credits" aria-label="Permalink to &quot;**Does using the assistant cost PodSEO credits?**&quot;">​</a></h3><p>No. Reading your data through an AI connection doesn&#39;t use credits.</p><h3 id="can-i-connect-more-than-one-assistant" tabindex="-1"><strong>Can I connect more than one assistant?</strong> <a class="header-anchor" href="#can-i-connect-more-than-one-assistant" aria-label="Permalink to &quot;**Can I connect more than one assistant?**&quot;">​</a></h3><p>Yes. You can connect Claude, ChatGPT and Cursor at the same time. Each one reads the account you approved for it, and you can disconnect each one separately.</p><h3 id="is-this-the-same-as-lucia" tabindex="-1"><strong>Is this the same as LUCIA?</strong> <a class="header-anchor" href="#is-this-the-same-as-lucia" aria-label="Permalink to &quot;**Is this the same as LUCIA?**&quot;">​</a></h3><p>No. <a href="/features/lucia-ai-assistant.html">LUCIA</a> is PodSEO&#39;s own assistant, built into the app, with PodSEO&#39;s guidance and the ability to make supported changes for you. AI connections let an outside assistant you choose read your PodSEO data, without making changes.</p><hr><h3 id="pro-tips" tabindex="-1"><strong>Pro Tips</strong> <a class="header-anchor" href="#pro-tips" aria-label="Permalink to &quot;**Pro Tips**&quot;">​</a></h3><ul><li>Start by asking the assistant to list your podcasts in PodSEO: it confirms the connection reads the right account.</li><li>Ask comparative questions that span several PodSEO pages, such as &quot;Which tracked keywords improved on Apple but dropped on Spotify in the last month?&quot;</li><li>When you ask about downloads, say which source you mean (your host, hopr.fm, Spotify, Apple): each counts something different, so the numbers aren&#39;t meant to be added together.</li><li>Ask the assistant for the date of the data it&#39;s using, especially for analytics, before drawing conclusions.</li><li>Use the assistant to draft reports for sponsors or your team, then check the key figures against PodSEO&#39;s pages.</li></ul>`,87)])])}const g=e(n,[["render",i]]);export{u as __pageData,g as default};
